<?php
require_once __DIR__ . '/../config.php';
requireAuth();

$pageTitle = 'Invoice Multiple';
$db = getDB();
$search=query('search',''); $customerId=query('customer_id',''); $invoiceType=query('invoice_type',''); $fromDate=query('from_date',''); $toDate=query('to_date',''); $status=query('status','');
$page=max(1,(int)query('page',1)); $perPage=25; $offset=($page-1)*$perPage;
$countSql="SELECT COUNT(*) FROM invoice_multiple im LEFT JOIN customers c ON c.id=im.customer_id WHERE 1=1";
$sql="SELECT im.*, c.name as customer_name FROM invoice_multiple im LEFT JOIN customers c ON c.id=im.customer_id WHERE 1=1"; $params=[];
if($search){$countSql.=" AND (im.invoice_no LIKE ? OR im.manual_book_no LIKE ? OR c.name LIKE ?)"; $sql.=" AND (im.invoice_no LIKE ? OR im.manual_book_no LIKE ? OR c.name LIKE ?)"; $params[]="%$search%"; $params[]="%$search%"; $params[]="%$search%";}
if($customerId){$countSql.=" AND im.customer_id=?"; $sql.=" AND im.customer_id=?"; $params[]=(int)$customerId;}
if($invoiceType && in_array($invoiceType,['customer','dukandar','karigar'])){$countSql.=" AND im.invoice_type=?"; $sql.=" AND im.invoice_type=?"; $params[]=$invoiceType;}
if($fromDate){$countSql.=" AND im.invoice_date>=?"; $sql.=" AND im.invoice_date>=?"; $params[]=$fromDate;}
if($toDate){$countSql.=" AND im.invoice_date<=?"; $sql.=" AND im.invoice_date<=?"; $params[]=$toDate;}
if($status && in_array($status,['active','cancelled'])){$countSql.=" AND im.status=?"; $sql.=" AND im.status=?"; $params[]=$status;} else {$countSql.=" AND im.status='active'"; $sql.=" AND im.status='active'";}
$total=$db->prepare($countSql); $total->execute($params); $totalCount=(int)$total->fetchColumn(); $lastPage=max(1,(int)ceil($totalCount/$perPage)); $page=min($page,$lastPage); $offset=($page-1)*$perPage;
$totalsSql = str_replace('SELECT im.*, c.name as customer_name', 'SELECT COALESCE(SUM(im.total_casting_weight),0) AS total_casting, COALESCE(SUM(im.effective_gold),0) AS total_effective, COALESCE(SUM(im.total_received_khalis),0) AS total_received, COALESCE(SUM(im.remaining_balance),0) AS total_balance', $sql);
$totalsStmt = $db->prepare($totalsSql); $totalsStmt->execute($params); $listTotals = $totalsStmt->fetch() ?: ['total_casting'=>0,'total_effective'=>0,'total_received'=>0,'total_balance'=>0];
$sql.=" ORDER BY im.invoice_date DESC, im.id DESC LIMIT $perPage OFFSET $offset"; $stmt=$db->prepare($sql); $stmt->execute($params); $invoices=$stmt->fetchAll();
$customers=$db->query("SELECT id,name FROM customers ORDER BY name")->fetchAll();
require_once __DIR__ . '/../includes/header.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Invoice Multiple</h1><p class="font-urdu" style="margin-top:4px;">ملٹی بل</p></div><div class="page-actions"><a href="<?= url('invoice-multiple/create.php') ?>" class="btn btn-gold"><i class="bi bi-plus-circle"></i> New Multiple Invoice</a></div></div>
<form method="GET" class="filter-bar"><div class="form-group" style="flex:1;"><input type="text" name="search" class="form-control" placeholder="Search invoice no, book no, party..." value="<?= htmlspecialchars($search) ?>"></div><div class="form-group"><select name="customer_id" class="form-control" onchange="this.form.submit()"><option value="">All Parties</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>" <?= $customerId==$c['id']?'selected':'' ?>><?= htmlspecialchars($c['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><select name="invoice_type" class="form-control" onchange="this.form.submit()"><option value="">All Types</option><option value="customer" <?= $invoiceType==='customer'?'selected':'' ?>>Customer</option><option value="dukandar" <?= $invoiceType==='dukandar'?'selected':'' ?>>Dukandar</option><option value="karigar" <?= $invoiceType==='karigar'?'selected':'' ?>>Karigar</option></select></div><div class="form-group"><input type="date" name="from_date" class="form-control" value="<?= htmlspecialchars($fromDate) ?>"></div><div class="form-group"><input type="date" name="to_date" class="form-control" value="<?= htmlspecialchars($toDate) ?>"></div><button type="submit" class="btn btn-primary"><i class="bi bi-search"></i></button><a href="<?= url('invoice-multiple/index.php') ?>" class="btn btn-outline"><i class="bi bi-x-circle"></i></a></form>
<div class="table-container"><table><thead><tr><th>Invoice #</th><th>Book #</th><th>Date</th><th>Type</th><th>Party</th><th class="text-right">Rows</th><th class="text-right">Casting (g)</th><th class="text-right">Effective (g)</th><th class="text-right">Received</th><th class="text-right">Balance</th><th>Status</th><th class="text-center">Actions</th></tr></thead><tbody><?php if(empty($invoices)): ?><tr><td colspan="12" class="text-center text-muted">No multiple invoices found</td></tr><?php else: foreach($invoices as $inv): ?><tr><td><a href="<?= url('invoice-multiple/show.php?id='.$inv['id']) ?>" style="color:var(--gold-primary);text-decoration:none;font-weight:600;"><?= htmlspecialchars($inv['invoice_no']) ?></a></td><td><?= htmlspecialchars($inv['manual_book_no'] ?: '-') ?></td><td><?= formatDate($inv['invoice_date']) ?></td><td><span class="badge bg-info"><?= ucfirst($inv['invoice_type']) ?></span></td><td><?= htmlspecialchars($inv['customer_name'] ?? 'N/A') ?></td><td class="text-right mono"><?php $rc=$db->prepare('SELECT COUNT(*) FROM invoice_multiple_items WHERE invoice_multiple_id=?'); $rc->execute([$inv['id']]); echo (int)$rc->fetchColumn(); ?></td><td class="text-right mono"><?= number_format($inv['total_casting_weight'],3) ?></td><td class="text-right mono"><?= number_format($inv['effective_gold'],3) ?></td><td class="text-right mono" style="color:var(--gold-primary);font-weight:600;"><?= number_format($inv['total_received_khalis'],3) ?></td><td class="text-right mono <?= $inv['remaining_balance'] < 0 ? 'text-danger':'text-success' ?>"><?= number_format($inv['remaining_balance'],3) ?></td><td><span class="badge <?= $inv['status']==='active'?'bg-success':'bg-danger' ?>"><?= ucfirst($inv['status']) ?></span></td><td class="text-center" style="white-space:nowrap;"><a href="<?= url('invoice-multiple/show.php?id='.$inv['id']) ?>" class="btn btn-sm btn-outline" title="View"><i class="bi bi-eye"></i></a> <?php if($inv['status']==='active'): ?><a href="<?= url('invoice-multiple/edit.php?id='.$inv['id']) ?>" class="btn btn-sm btn-outline" title="Edit"><i class="bi bi-pencil"></i></a> <?php endif; ?><a href="<?= url('invoice-multiple/print.php?id='.$inv['id']) ?>" class="btn btn-sm btn-outline" title="Print"><i class="bi bi-printer"></i></a><?php if($inv['status']==='active'): ?> <a href="<?= url('invoice-multiple/delete.php?id='.$inv['id']) ?>" class="btn btn-sm btn-danger" onclick="return confirm('Cancel multiple invoice <?= htmlspecialchars($inv['invoice_no']) ?>?')"><i class="bi bi-trash"></i></a><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody><tfoot><tr style="font-weight:700;background:var(--bg-surface);border-top:2px solid var(--gold-primary);"><td colspan="6">Filtered Total (<?= number_format((float)$totalCount) ?> records)</td><td class="text-right mono"><?= number_format($listTotals['total_casting'],3) ?></td><td class="text-right mono"><?= number_format($listTotals['total_effective'],3) ?></td><td class="text-right mono"><?= number_format($listTotals['total_received'],3) ?></td><td class="text-right mono"><?= number_format($listTotals['total_balance'],3) ?></td><td colspan="2"></td></tr></tfoot></table></div>
<?php if($lastPage>1): $urlTemplate=url('invoice-multiple/index.php?'.http_build_query(array_merge($_GET,['page'=>'__PAGE__']))); ?><div class="pagination"><nav><ul class="pagination-list"><li class="page-item <?= $page<=1?'disabled':'' ?>"><a class="page-link" href="<?= str_replace('__PAGE__',$page-1,$urlTemplate) ?>">&laquo;</a></li><?php for($i=1;$i<=$lastPage;$i++): ?><li class="page-item <?= $i===$page?'active':'' ?>"><a class="page-link" href="<?= str_replace('__PAGE__',$i,$urlTemplate) ?>"><?= $i ?></a></li><?php endfor; ?><li class="page-item <?= $page>=$lastPage?'disabled':'' ?>"><a class="page-link" href="<?= str_replace('__PAGE__',$page+1,$urlTemplate) ?>">&raquo;</a></li></ul></nav></div><?php endif; ?>
<?php require_once __DIR__ . '/../includes/footer.php'; ?>
